// spec: specs/client-ordering.md §11 · кейс .qa/tests/client-ordering/co-32-cart-add-from-upsell-rows.md (+ co-31, co-23)
// seed: tests/seed.buyer.spec.ts
// #c2fc80 (עבר QA 27.10, commit af34d69): в корзине с 3 строками «הוספה לעגלה» из блока «השלימו את ההזמנה» — строки, которые уже
//   были в корзине, остаются видны на каждом кадре (не заменяются скелетами), корзина не «опустевает»; скелет допустим только для
//   новой строки и для суммы («מה רצוי» — «אפשר שלד רק לשורה החדשה ולסכום»). Сумма — никогда «₪0.00» (#b82eba). В итоге 4 строки,
//   сумма = сумма строк.
// НЕ проверяется: блок «השלימו את ההזמנה» может скрываться на ~0.3 с, пока не придут новые рекомендации (не требование тикета);
//   кнопка «המשך לביצוע הזמנה» на миг disabled — намеренно (коммент программиста).
// Кадры ловит MutationObserver с момента перед кликом. Второй прогон — задержка ответа rpc/customer_products 1.5 с
//   (route.continue() после паузы, ответ не подменяется). Ширины тикета: 1440 и 390 (эмуляция ширины в том же проекте).
// Корзина buyer общая и серверная → @data, serial, один проект (@desktop); не параллельно с cart-checkout / order-lifecycle /
//   inventory-lifecycle / cart-remove-no-flash / cart-total-loading-skeleton. Корзина в конце — ПУСТАЯ (по заданию пользователя
//   27.10); если до теста в ней что-то было — снимок записывается в аннотацию «cart-before». Заказ не оформляется.
import { test, expect, Page } from '@playwright/test';
import { auth, emptyCart } from '../orders/_qa-order';
import { cartSnapshot } from './_cart-snapshot';

test.use({ storageState: auth('buyer'), viewport: { width: 1440, height: 900 } });
test.describe.configure({ mode: 'serial' });

const PRICES = /supabase\.co\/rest\/v1\/rpc\/customer_products/;
type Frame = { names: string[]; rowSkeletons: number; empty: boolean; total: string; totalPulse: boolean };

const removeBtns = (page: Page) => page.getByRole('button', { name: /^הסרה מהעגלה — / });
const sumRow = (page: Page) => page.getByText('סה״כ משוער', { exact: true }).locator('..');
const upsell = (page: Page) => page.locator('section', { has: page.getByRole('heading', { name: 'השלימו את ההזמנה' }) });
const cents = (s: string) => Math.round(Number(s.replace(/[₪,]/g, '')) * 100);
const fmt = (c: number) => '₪' + (c / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

/** Запись кадров корзины с момента вызова: имена строк, скелеты в списке строк, «העגלה ריקה», сумма. */
async function startRecording(page: Page) {
  await page.evaluate(() => {
    const w = window as unknown as { __frames: unknown[] };
    w.__frames = [];
    const RM = 'button[aria-label^="הסרה מהעגלה — "]';
    // список строк = общий родитель карточек строк (карточка — самый широкий предок с одной кнопкой «הסרה מהעגלה»)
    const first = document.querySelector(RM)!;
    let row: Element = first;
    while (row.parentElement && row.parentElement.querySelectorAll(RM).length === 1) row = row.parentElement;
    const list = row.parentElement!;
    const snap = () => {
      const names = [...document.querySelectorAll(RM)].filter((b) => b.getClientRects().length > 0)
        .map((b) => b.getAttribute('aria-label')!.replace('הסרה מהעגלה — ', ''));
      // скелеты строк: дети списка (или сам список, если он заменён) с .animate-pulse и без кнопки удаления
      const liveList = list.isConnected ? list : document.body;
      const rowSkeletons = [...liveList.children].filter((c) => c.querySelector('.animate-pulse') || c.classList.contains('animate-pulse'))
        .filter((c) => !c.querySelector(RM) && !/השלימו את ההזמנה|סה״כ משוער/.test(c.textContent || '')).length;
      const lab = [...document.querySelectorAll('body *')].find((e) => e.children.length === 0 && (e.textContent || '').trim() === 'סה״כ משוער');
      const r = lab?.parentElement;
      w.__frames.push({
        names, rowSkeletons, empty: /העגלה ריקה/.test(document.body.textContent || ''),
        total: ((r?.textContent || '').match(/₪[\d,]+\.\d\d/) || [''])[0], totalPulse: !!r?.querySelector('.animate-pulse'),
      });
    };
    snap();
    new MutationObserver(snap).observe(document.documentElement, { childList: true, subtree: true, characterData: true, attributes: true });
  });
}
const frames = (page: Page) => page.evaluate(() => (window as unknown as { __frames: Frame[] }).__frames);

/** Сумма строк корзины (цена в карточке строки; все строки по 1 шт.). */
async function linesTotal(page: Page) {
  const prices = await removeBtns(page).evaluateAll((btns) => btns.map((b) => {
    let card: Element = b;
    while (card.parentElement && card.parentElement.querySelectorAll('button[aria-label^="הסרה מהעגלה"]').length === 1) card = card.parentElement;
    return [...card.querySelectorAll('*')].map((e) => (e.children.length === 0 ? (e.textContent || '').trim() : '')).find((t) => /^₪[\d,]+\.\d\d$/.test(t)) || '';
  }));
  expect(prices.filter((p) => !p), 'у каждой строки есть цена').toEqual([]);
  return prices.reduce((s, p) => s + cents(p), 0);
}

/** /shop → «הוספה לעגלה» для 3 товаров с ценой ≠ ₪0.00 → корзина с 3 строками. Возвращает имена. */
async function fillCartWith3(page: Page) {
  await emptyCart(page);
  await page.goto('/shop');
  await expect(page.getByRole('button', { name: /^הוספה לעגלה — / }).first()).toBeVisible({ timeout: 30_000 });
  const names = await page.evaluate(() => {
    const out: string[] = [];
    for (const art of document.querySelectorAll('article')) {
      const b = art.querySelector('button[aria-label^="הוספה לעגלה — "]') as HTMLButtonElement | null;
      const price = ((art.textContent || '').match(/₪[\d,]+\.\d\d/) || [''])[0];
      if (b && !b.disabled && price && price !== '₪0.00') out.push(b.getAttribute('aria-label')!.replace('הוספה לעגלה — ', ''));
    }
    return [...new Set(out)].slice(0, 3);
  });
  expect(names.length, 'в каталоге есть 3 товара с ценой ≠ ₪0.00').toBe(3);
  for (const n of names) {
    const added = page.waitForResponse((r) => r.url().includes('cart_set_item'));
    await page.getByRole('button', { name: `הוספה לעגלה — ${n}`, exact: true }).first().click();
    await added;
  }
  await page.goto('/shop/cart');
  await expect(page.getByRole('heading', { name: 'העגלה שלי' })).toBeVisible({ timeout: 30_000 });
  await expect(removeBtns(page)).toHaveCount(3, { timeout: 20_000 });
  await expect(sumRow(page)).toContainText(fmt(await linesTotal(page)), { timeout: 20_000 });
  await expect(page.locator('.animate-pulse'), 'корзина загружена — скелетов нет').toHaveCount(0);
  return names;
}

/** Добавление из «השלימו את ההזמנה» и проверка кадров. */
async function addFromUpsellAndCheck(page: Page, before: string[], tag: string, slow = false) {
  const btn = upsell(page).getByRole('button', { name: /^הוספה לעגלה — / }).first();
  await expect(btn, `${tag}: блок «השלימו את ההזמנה» с товаром`).toBeVisible({ timeout: 20_000 });
  const name = (await btn.getAttribute('aria-label'))!.replace('הוספה לעגלה — ', '');
  expect(before, `${tag}: рекомендованного товара ещё нет в корзине`).not.toContain(name);
  await startRecording(page);
  const added = page.waitForResponse((r) => r.url().includes('cart_set_item'));
  await btn.click();
  await added;
  // итог: 4 строки, сумма = сумма строк, «פריטים בעגלה 4»
  await expect(removeBtns(page), `${tag}: новая строка добавлена`).toHaveCount(4, { timeout: 20_000 });
  await expect(page.getByRole('button', { name: `הסרה מהעגלה — ${name}` })).toBeVisible();
  await expect(sumRow(page).locator('.animate-pulse'), `${tag}: скелет суммы исчез`).toHaveCount(0, { timeout: 20_000 });
  const total = fmt(await linesTotal(page));
  await expect(sumRow(page), `${tag}: «סה״כ משוער» = сумма 4 строк ${total}`).toContainText(total);
  await expect(page.getByText('פריטים בעגלה', { exact: true }).locator('..')).toContainText('4');

  const f = await frames(page);
  expect(f.length, `${tag}: кадры записаны`).toBeGreaterThan(1);
  // строки, которые уже были, видны на каждом кадре; корзина не опустевает
  expect(f.filter((x) => before.some((n) => !x.names.includes(n))).slice(0, 3), `${tag}: ни на одном кадре существующие строки не пропадают`).toEqual([]);
  expect(f.filter((x) => x.empty), `${tag}: ни одного кадра «העגלה ריקה»`).toEqual([]);
  // скелет — максимум для одной (новой) строки
  expect(f.filter((x) => x.rowSkeletons > 1).slice(0, 3), `${tag}: скелет только для новой строки (≤ 1)`).toEqual([]);
  // сумма — скелет или верная сумма, никогда ₪0.00 (#b82eba)
  expect(f.filter((x) => x.total === '₪0.00'), `${tag}: ни одного кадра «סה״כ משוער ₪0.00»`).toEqual([]);
  expect(f.filter((x) => !x.total && !x.totalPulse), `${tag}: без суммы — только скелет`).toEqual([]);
  expect(f[f.length - 1].total, `${tag}: последний кадр — верная сумма`).toBe(total);
  // при медленном ответе цен состояние загрузки было записано (скелет суммы/новой строки) — запись кадров работает
  if (slow) expect(f.some((x) => x.totalPulse || x.rowSkeletons > 0), `${tag}: кадры загрузки записаны`).toBe(true);
}

test.describe('client-ordering — עגלה: השורות נשארות בהוספה מ«השלימו את ההזמנה» (#c2fc80)', () => {
  test.beforeAll(async ({ browser }) => {
    test.setTimeout(120_000);
    const ctx = await browser.newContext({ storageState: auth('buyer'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    const snap = await cartSnapshot(await ctx.newPage());
    if (snap.length) test.info().annotations.push({ type: 'cart-before', description: JSON.stringify(snap) });
    await ctx.close();
  });

  test.afterAll(async ({ browser }) => {
    test.setTimeout(120_000);
    const ctx = await browser.newContext({ storageState: auth('buyer'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    await emptyCart(await ctx.newPage()); // корзина в конце пустая
    await ctx.close();
  });

  test('1440, 3 שורות ← «הוספה לעגלה» מ«השלימו»: השורות הקיימות בכל פריים, שלד רק לשורה החדשה, בלי ₪0.00; אחר כך 4 שורות והסכום הנכון #c2fc80 @desktop @orders @data', async ({ page }) => {
    test.setTimeout(120_000);
    const before = await fillCartWith3(page);
    await addFromUpsellAndCheck(page, before, '1440');
  });

  test('1440, תגובת customer_products מתעכבת 1.5 ש׳: אותו דבר — העגלה לא «מתרוקנת» #c2fc80 @desktop @orders @data', async ({ page }) => {
    test.setTimeout(120_000);
    const before = await fillCartWith3(page);
    await page.route(PRICES, async (route) => {
      await new Promise((r) => setTimeout(r, 1500)); // эмуляция медленной сети, не пауза теста
      await route.continue();
    });
    await addFromUpsellAndCheck(page, before, '1440, задержка 1.5 с', true);
    await page.unroute(PRICES);
  });

  test('390 (רוחב באמולציה): אותו דבר — השורות הקיימות בכל פריים #c2fc80 @desktop @orders @data', async ({ page }) => {
    test.setTimeout(120_000);
    await page.setViewportSize({ width: 390, height: 844 });
    const before = await fillCartWith3(page);
    await addFromUpsellAndCheck(page, before, '390');
  });
});
